import{_ as r,C as t,c as s,o as c,a9 as l,G as a}from"./chunks/framework.BAB8_kX7.js";const b=JSON.parse('{"title":"从 V4 升级","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/ExcellentEnchants"},{"title":"从 V4 升级","link":"/ExcellentEnchants/upgrading-from-v4"}]},"headers":[],"relativePath":"ExcellentEnchants/upgrading-from-v4.md","filePath":"ExcellentEnchants/upgrading-from-v4.md"}'),i={name:"ExcellentEnchants/upgrading-from-v4.md"};function p(d,e,h,g,m,u){const o=t("NolebaseGitContributors"),n=t("NolebaseGitChangelog");return c(),s("div",null,[e[0]||(e[0]=l('<h1 id="从-v4-升级" tabindex="-1">从 V4 升级 <a class="header-anchor" href="#从-v4-升级" aria-label="Permalink to &quot;从 V4 升级&quot;">​</a></h1><p>自 v5 版本起，ExcellentEnchants 在 PaperMC 服务器上使用 Paper 注册表 API 来注册附魔，建议在<strong>自定义命名空间</strong>下进行注册。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>正因如此，为了同时支持 Spigot 与 Paper 服务端，插件代码有了许多<strong>内部改动</strong>。同样借此引入了大量<strong>配置改动</strong>。</p></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>无论如何，重新安装总是很不错的选择。</p></div><h2 id="命名空间" tabindex="-1">命名空间 <a class="header-anchor" href="#命名空间" aria-label="Permalink to &quot;命名空间&quot;">​</a></h2><p>默认情况下所有附魔都使用 <code>excellentenchants</code> 命名空间。这意味着从 v4 迁移来的附魔会在服务器安装 v5 版本时<strong>永久删除</strong>，因为旧附魔的命名空间都是 <code>minecraft</code>。</p><p>如果需要在升级 v5 的同时保留附魔，你需要在开发环境中<strong>预生成</strong>所有新配置，并在投入生产前禁用<a href="./features.compatibility#命名空间">自定义命名空间</a>。</p><h2 id="分布" tabindex="-1">分布 <a class="header-anchor" href="#分布" aria-label="Permalink to &quot;分布&quot;">​</a></h2><p>全局分布与禁用附魔已移动至<a href="./features.disabling">对应的配置文件</a>。在投入生产环境前，请根据你的 v4 设置对其修改。</p><h2 id="附魔设置" tabindex="-1">附魔设置 <a class="header-anchor" href="#附魔设置" aria-label="Permalink to &quot;附魔设置&quot;">​</a></h2><p>附魔设置<strong>不会兼容</strong>，你需要备份当前的 <code>/enchant/</code> 文件夹，并重新生成一份。之后，你就可以根据 v4 设置对其进行更改。</p><div class="danger custom-block"><p class="custom-block-title">危险</p><p>不要尝试带着 <code>/enchants/</code> 中的 v4 附魔升级！</p><p>配置文件会被打乱，并且插件也会无法载入它们。</p><p><strong>后果自负。</strong></p></div>',12)),a(o),a(n)])}const v=r(i,[["render",p]]);export{b as __pageData,v as default};
